-- =============================================================================
-- Migration V12: Create Survey tables (Module 4)
-- Tables: survey_time_slots, booking_surveys, survey_attachments
-- So với schema leader: status dùng varchar + Java enum (thêm IN_PROGRESS, RESURVEY_REQUIRED),
-- thêm actual_start_at / actual_end_at, survey_staff_id trỏ staff(user_id) như bookings.customer_id.
-- =============================================================================

-- 1. Khung giờ khảo sát
CREATE TABLE IF NOT EXISTS "survey_time_slots" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "start_time" time NOT NULL,
  "end_time" time NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  CONSTRAINT chk_survey_time_slots_range CHECK (end_time > start_time)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_survey_time_slots_range ON "survey_time_slots" ("start_time", "end_time");

-- 2. Lịch khảo sát (mỗi lần khảo sát / khảo sát lại = 1 bản ghi)
CREATE TABLE IF NOT EXISTS "booking_surveys" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "survey_method" varchar(20) NOT NULL,
  "survey_date" date,
  "survey_time_slot_id" int,
  "survey_staff_id" bigint,
  "status" varchar(30) NOT NULL DEFAULT 'PENDING',
  "actual_start_at" timestamp,
  "actual_end_at" timestamp,
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_booking_surveys_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surveys_time_slot FOREIGN KEY ("survey_time_slot_id") REFERENCES "survey_time_slots" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_surveys_staff FOREIGN KEY ("survey_staff_id") REFERENCES "staff" ("user_id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_booking_surveys_actual_range CHECK (actual_end_at IS NULL OR actual_start_at IS NULL OR actual_end_at >= actual_start_at),
  -- Đã lên lịch trở đi thì phải có đủ ngày + khung giờ + nhân viên
  CONSTRAINT chk_booking_surveys_scheduled_fields CHECK (
    status NOT IN ('CONFIRMED', 'IN_PROGRESS', 'COMPLETED')
    OR (survey_date IS NOT NULL AND survey_time_slot_id IS NOT NULL AND survey_staff_id IS NOT NULL)
  )
);

CREATE INDEX IF NOT EXISTS idx_booking_surveys_booking_id ON "booking_surveys" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_booking_surveys_staff_date ON "booking_surveys" ("survey_staff_id", "survey_date");
CREATE INDEX IF NOT EXISTS idx_booking_surveys_date_status ON "booking_surveys" ("survey_date", "status");

-- Mỗi booking tối đa 1 khảo sát đang hoạt động
CREATE UNIQUE INDEX IF NOT EXISTS uq_booking_surveys_one_active_per_booking
  ON "booking_surveys" ("booking_id")
  WHERE status IN ('PENDING', 'CONFIRMED', 'IN_PROGRESS');

-- Một nhân viên không thể có 2 khảo sát cùng ngày + cùng khung giờ
CREATE UNIQUE INDEX IF NOT EXISTS uq_booking_surveys_staff_slot
  ON "booking_surveys" ("survey_staff_id", "survey_date", "survey_time_slot_id")
  WHERE status IN ('CONFIRMED', 'IN_PROGRESS');

-- 3. Tệp đính kèm khảo sát
CREATE TABLE IF NOT EXISTS "survey_attachments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "survey_id" int NOT NULL,
  "file_url" varchar(1000) NOT NULL,          -- lưu key / public_id của nơi lưu trữ, không lưu URL đầy đủ
  "file_type" varchar(20) NOT NULL DEFAULT 'IMAGE',
  "uploaded_by" bigint,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_survey_attachments_survey FOREIGN KEY ("survey_id") REFERENCES "booking_surveys" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_survey_attachments_uploaded_by FOREIGN KEY ("uploaded_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX IF NOT EXISTS idx_survey_attachments_survey_id ON "survey_attachments" ("survey_id");

-- 4. Seed khung giờ khảo sát mẫu
